from pathlib import Path
import json,html
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];STUDY=ROOT/'data/analysis/reversal-deep-20260929'
E=html.escape
fmt=lambda x:f'{x:+.3f}%' if x is not None and np.isfinite(x) else '—'
num=lambda x:f'{x:.3f}' if x is not None and np.isfinite(x) else '—'
def table(head,rows):return '<div class="scroll"><table><thead><tr>'+''.join(f'<th>{E(str(x))}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{E(str(x))}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def main():
    s=json.loads((HERE/'summary.json').read_text());w=pd.read_json(HERE/'window_results.jsonl',lines=True);tr=pd.read_json(HERE/'strategy_trades.jsonl',lines=True)
    results=s['strategies'];passed=[k for k,v in results.items() if v['verified_AI_strategy']]
    title='A frozen AI reversal rule passed historical validation' if passed else 'No AI reversal rule passed the frozen verification criteria'
    budget=json.loads((STUDY/'snapshot_budget.json').read_text());attempts=len(budget['reserved_attempts'])
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
    fig,ax=plt.subplots(1,3,figsize=(15,4.8))
    discl=pd.read_csv(STUDY/'signals/candidate_results.csv');discs=pd.read_csv(STUDY/'risk/all_trials.csv');disc=[float(discl[(discl.side=='long')&(discl.gate=='none')&(discl.wait==15)&(discl.hold==240)].iloc[0].net_mean),float(discs[(discs.policy_id==764)&(discs.gate=='all')&(discs.strategy=='reverse_long_to_short')].iloc[0].mean_net_pct)];positions=np.arange(2);cols=['#13796d','#b75a20']
    ax[0].bar(positions-.18,disc,.36,color='#9caaa3',label='Discovery (selected)')
    ax[0].bar(positions+.18,[results[k]['mean_net_pct'] for k in ['L','S']],.36,color=cols,label='Fresh validation')
    ax[0].axhline(0,color='#555',lw=1);ax[0].set_xticks(positions,['L: confirmed long','S: capped short']);ax[0].set_ylabel('Mean net per trade (%)');ax[0].set_title('Discovery versus 280 fresh windows');ax[0].legend(fontsize=8)
    for i,k in enumerate(['L','S']):
        r=results[k];mu=r['mean_net_pct'];lo,hi=r['simultaneous_ci975_mean_net_pct'];ax[1].errorbar(mu,1-i,xerr=[[mu-lo],[hi-mu]],fmt='o',color=cols[i],capsize=5);ax[1].text(mu,1-i+.12,f"n={r['n']}",ha='center',fontsize=9)
        x=tr.loc[tr.strategy==k,'net_pct'].to_numpy();ax[2].scatter(x,np.full(len(x),1-i)+(np.arange(len(x))%7-3)*.035,s=15,alpha=.65,color=cols[i])
    for a in ax[1:]:a.axvline(0,color='#555',lw=1);a.set_yticks([1,0],['L: long','S: short']);a.set_ylim(-.4,1.4);a.set_xlabel('Net return (%)')
    ax[1].set_title('Means with simultaneous intervals\n97.5% per rule; 95% family coverage');ax[2].set_title('Every executed trade\n20 bps deducted per trade')
    fig.suptitle('Terra reversal research · rules frozen before fresh decisions',fontsize=15);fig.text(.5,.015,'Historical SOL archive. Arithmetic per-trade returns, no portfolio compounding. Independent AI-selection tests and controls shown in report.',ha='center',fontsize=8);fig.tight_layout(rect=[0,.04,1,.91]);fig.savefig(HERE/'overview.png',dpi=160);fig.savefig(HERE/'overview.pdf');plt.close(fig)
    primary=[];ai=[];robust=[];pay=[]
    for k,r in results.items():
        primary.append([k,r['n'],f"{r['gross_positive']}/{r['n']} ({r['gross_win_rate']:.1%})",f"{r['net_positive']}/{r['n']}",fmt(r['mean_gross_pct']),fmt(r['mean_net_pct']),fmt(r['mean_net_per_opportunity_pct']),' to '.join(fmt(x) for x in r['simultaneous_ci975_mean_net_pct']),str(r['verified_AI_strategy'])])
        a=r['AI_selection'];ai.append([k,fmt(a['conditional_null_mean_net_pct']),fmt(a['increment_over_conditional_null_pct']),num(a['p_one_sided']),num(a['p_holm_two_tests'])])
        robust.append([k,fmt(r['mean_net_at30bps_pct']),fmt(r['entry_delay_sensitivity']['1']['mean_net_pct']),fmt(r['entry_delay_sensitivity']['5']['mean_net_pct']),' / '.join(fmt(x['mean_net_pct']) for x in r['chronological_thirds']),' to '.join(fmt(x) for x in r['quarter_cluster_ci95_net_pct']),fmt(r['mean_net_excluding_best3_pct'])])
        win=r['mean_gross_winner_pct'];loss=r['mean_gross_loser_pct'];required=(abs(loss)+.2)/(win+abs(loss)) if win and loss else None
        pay.append([k,fmt(win),fmt(loss),f'{required:.1%}' if required else '—',num(r['profit_factor_net']),fmt(r['worst_gross_pct']),f"{r['break_even_roundtrip_bps']:.1f} bps"])
    baseline=table(['Control','Trades','Mean gross','Mean net','Net/opportunity'],[[k,r['n'],fmt(r.get('mean_gross_pct')),fmt(r.get('mean_net_pct')),fmt(r.get('mean_net_per_opportunity_pct'))] for k,r in s['controls'].items()])
    cards=[]
    for r in w.to_dict('records'):
        case=int(r['case']);actual=tr[tr.case==case];out=[]
        for t in actual.to_dict('records'):out.append([t['strategy'],t['strategy_side'],t['entry_time'],t['exit_minute_close_time'],t['outcome'],f"{t['entry_price']:.6g} → {t['exit_price']:.6g}",fmt(t['gross_pct']),fmt(t['net_pct'])])
        tab=table(['Rule','Side','Entry UTC','Exit minute close UTC','Outcome','Prices','Gross','Net'],out) if out else '<p>No finalist trade: AI short but the 15-minute positive confirmation failed.</p>'
        cards.append(f'<section id="case-{case}"><h2>Case {case:03d} · Terra {E(r["ai_action"].upper())}</h2><p class="muted">Research metadata only: SOL-USD · {E(str(r["original_entry_time"]))} UTC · {E(r["regime"])} · {E(r["window_id"])}</p><p><strong>Saved explanation:</strong> {E(r["reason"])} Confidence {r["confidence"]:.0%}; original AI stop {100*r["ai_stop_pct"]:.2f}%.</p>{tab}<details><summary>Inspect exact anonymized model input</summary><img loading="lazy" src="stimuli/case{case:03d}/chart.png" alt="Exact model chart, case {case}"><p><a href="stimuli/case{case:03d}/input.txt">Complete supplied text</a></p></details></section>')
    conclusion='At least one frozen rule passed the stated historical criteria; see uncertainty, controls and limitations below.' if passed else 'The discovery search found attractive historical cells, but neither frozen finalist satisfied the full fresh verification requirements. Positive averages or high win rates alone are not treated as success.'
    criteria=table(['Rule','>=50 trades','Profit CI >0','30bps >0','Both delays >0','AI test passed','Leave-one-third-out >0'],[[k,r['verification']['at_least50_executed'],r['verification']['simultaneous_net_CI_positive'],r['verification']['30bps_mean_positive'],r['verification']['both_delay_means_positive'],r['verification']['AI_increment_positive_and_significant'],r['single_period_dependence_check_passed']] for k,r in results.items()])
    behavior=w.groupby('regime').agg(n=('case','size'),ai_long=('ai_action',lambda x:(x=='long').sum()));behavior['long_fraction']=behavior.ai_long/behavior.n
    style='body{margin:0;background:#f5f5ef;color:#25382f;font:15px/1.65 system-ui}main{max-width:1500px;margin:auto;padding:34px}h1{font-size:35px;line-height:1.2}h2{font-size:23px}section{background:#fff;border:1px solid #dce4dc;padding:22px;border-radius:10px;margin:22px 0}a{color:#147869}.notice{background:#f9ead5;border-left:4px solid #b75a20;padding:18px}.muted{color:#68736e;font-size:13px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px 12px;border-bottom:1px solid #dce4dc;text-align:left;white-space:nowrap}th{background:#edf2e9}img{max-width:100%;height:auto}summary{cursor:pointer}'
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><style>{style}</style></head><body><main><p class="muted">280 fresh historical windows · {attempts}/300 authorized snapshot attempts · Terra medium</p><h1>{E(title)}</h1><p class="notice">{E(conclusion)}</p><p><strong>L:</strong> Terra SHORT → wait 15 minutes; if price closes above the original entry, buy next minute's open and exit 240 minutes later. <strong>S:</strong> Terra LONG → short at the original close; stop 1.5× AI stop, target 2× strategy stop, timeout 240 minutes. The rules were locked before fresh inputs or decisions. No tuning on this validation batch.</p><p><a href="FINDINGS.md">Written findings</a> · <a href="../../analysis/reversal-deep-20260929/VALIDATION_PROTOCOL.md">Locked protocol</a> · <a href="../../analysis/reversal-deep-20260929/VERIFICATION_INTERPRETATION.md">Pre-outcome interpretation</a> · <a href="strategy_trades.csv">Every executed trade</a> · <a href="window_results.csv">All 280 windows including skips and controls</a> · <a href="summary.json">Full statistics</a> · <a href="overview.pdf">Export figure</a></p><img src="overview.png" alt="Discovery and fresh results, simultaneous net intervals, and every trade"><section><h2>Fresh primary results</h2>{table(['Rule','Trades','Gross wins','Net wins','Mean gross/trade','Mean net/trade','Net/opportunity','Simultaneous net interval','Verified'],primary)}<p>Net subtracts 20 bps roundtrip. These are arithmetic mean returns, not compounded portfolio returns. Opportunity means include zero for skipped windows. Bracket ambiguity is stop-first and favorable target gaps receive no price improvement.</p>{criteria}</section><section><h2>Did the AI add information?</h2>{table(['Rule','Conditional null mean net','AI increment','Permutation p','Holm p (2 tests)'],ai)}<p>20,000 permutations preserve broad market regimes and eras. L shuffles action labels; S shuffles action and stop/ATR ratio jointly and replays recipient price paths at recipient volatility. This tests information beyond those coarse conditions, not every possible price-only model. Counts and decision vectors remain intact within strata.</p>{baseline}<p>The all-window AI-width short control isolates direction selection but still uses AI-generated risk geometry. ATR controls are genuinely price-only. The ATR2/targetATR2 policy is a prespecified diagnostic and cannot replace a failed primary finalist.</p></section><section><h2>Risk, costs and stability</h2>{table(['Rule','Net at 30 bps','Net:1m delay','Net:5m delay','Chronological thirds:net','Quarter-bootstrap95% CI','Net excluding top3'],robust)}{table(['Rule','Avg gross winner','Avg gross loser','Break-even win rate at 20 bps','Net profit factor','Worst gross','Break-even total costs'],pay)}<p>Short primary entry assumes instantaneous inference. Delays enter 1/5 minutes later and preserve the original exit clock; brackets recenter at the delayed entry. Long entry already waits for the confirmation candle. Funding, borrow, market impact and venue-specific fees are not modeled. Removing winners is only a concentration check, never a new trading rule.</p></section><section><h2>Behavior and search history</h2>{table(['MA regime','Windows','AI longs','Long fraction'],[[k,int(r.n),int(r.ai_long),f'{r.long_fraction:.1%}'] for k,r in behavior.iterrows()])}<p>The discovery work retained 824 risk/exit geometries (12,360 direction/regime summaries), 116 entry/filter candidates and 108 invalidation policies. Its 150 market windows were already observed. The selected cells were not considered validation. The new 280 windows span all MA regimes and are separated by at least 74 hours from each other, with asymmetric exclusions around all 156 prior entries.</p><p><a href="../../analysis/reversal-deep-20260929/risk/FINDINGS.md">Risk discovery</a> · <a href="../../analysis/reversal-deep-20260929/signals/FINDINGS.md">Signal discovery</a> · <a href="../../analysis/reversal-deep-20260929/confirmation/all_policy_summaries.csv">All invalidation candidates</a> · <a href="../../analysis/reversal-deep-20260929/design/validation_precollection_audit.json">Precollection audit</a> · <a href="scoring_audit.json">Scoring audit</a> · <a href="isolation_audit.json">Isolation audit</a></p><p>Historical SOL-only archive, not live or chronological future evidence; anonymization does not establish data unknown in model training. Residual regime dependence remains possible. The search/holdout separation follows the concern described in <a href="https://www.davidhbailey.com/dhbpapers/backtest-prob.pdf">Bailey et al., The Probability of Backtest Overfitting</a>.</p></section><h2>Every fresh case</h2><p>{' · '.join(f'<a href="#case-{i}">{i:03d}</a>' for i in range(1,281))}</p>{''.join(cards)}</main></body></html>'''
    (HERE/'index.html').write_text(doc)
    lines=[f'# {title}','',conclusion,'',f'All 280 fresh isolated Terra decisions collected using {attempts} physical calls. Remaining authorization: {300-attempts} calls, reserved for validity failures rather than outcome-dependent tuning. Old inputs, source and reports preserved.','', '| Frozen rule | Executions | Gross wins | Mean gross | Mean net at 20 bps | Simultaneous net CI | AI Holm p |','|---|---:|---:|---:|---:|---|---:|']
    for k,r in results.items():lines.append(f"|{k}|{r['n']}|{r['gross_positive']}/{r['n']}|{fmt(r['mean_gross_pct'])}|{fmt(r['mean_net_pct'])}|{' to '.join(fmt(x) for x in r['simultaneous_ci975_mean_net_pct'])}|{num(r['AI_selection']['p_holm_two_tests'])}|")
    lines+=['','L = AI SHORT, positive first 15m confirmation, then long 240m. S = AI LONG, short with 1.5× AI-stop risk, 2× risk target and 240m cap. Both rules were frozen before fresh data collection.','', 'The hypothesis that AI makes systematically exploitable mistakes requires two separate pieces of evidence: positive net expectancy and incremental value from AI selection. The table distinguishes them. The complete report includes controls, costs, latency sensitivities, tail dependence, chronological and quarter-cluster diagnostics, exact model explanations and every skipped window.','', 'A large discovery search was completed, but its attractive cells are not verified results. At the earlier payoff sizes, a 57% short win rate required about 75% to cover 20 bps; replaying actual stop/target paths was necessary.','', 'Historical simulation only. Fixed costs omit funding, borrow and market impact; original-close short entry ignores inference latency. No live or cross-asset claim.','',f'[Open complete report](index.html) · [All executed trades](strategy_trades.csv) · [All windows and controls](window_results.csv) · [Full summary](summary.json) · [Frozen protocol](../../analysis/reversal-deep-20260929/VALIDATION_PROTOCOL.md)']
    (HERE/'FINDINGS.md').write_text('\n'.join(lines)+'\n')
    (STUDY/'PRIMARY_RESULTS.md').write_text('\n'.join(lines).replace('(index.html)',f'(../../sim/{s["run_id"]}/index.html)').replace('(strategy_trades.csv)',f'(../../sim/{s["run_id"]}/strategy_trades.csv)').replace('(window_results.csv)',f'(../../sim/{s["run_id"]}/window_results.csv)').replace('(summary.json)',f'(../../sim/{s["run_id"]}/summary.json)').replace('(../../analysis/reversal-deep-20260929/VALIDATION_PROTOCOL.md)','(VALIDATION_PROTOCOL.md)')+'\n')
    print(json.dumps({'report':str(HERE/'index.html'),'verified_rules':passed,'attempts':attempts}))
if __name__=='__main__':main()
